#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";

const sourceRoot = process.argv[2];
const apply = process.argv.includes("--apply");
if (!sourceRoot) {
  console.error("Usage: node Scripts/normalize-kannada-glossary-context.mjs <English-assets-dir> [--apply]");
  process.exit(2);
}

const projectRoot = path.resolve(import.meta.dirname, "..");
const translationRoot = path.join(
  projectRoot,
  "Sources/StardewTranslationInstaller/Resources/ModPayload/assets/translations/kannada",
);

function readJSON(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function boundaryExpression(value, flags = "iu") {
  const escaped = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const left = /^[\p{L}\p{N}]/u.test(value) ? "(?<![\\p{L}\\p{N}])" : "";
  const right = /[\p{L}\p{N}]$/u.test(value) ? "(?![\\p{L}\\p{N}])" : "";
  return new RegExp(`${left}${escaped}${right}`, flags);
}

const sourceCache = new Map();
function sourceContent(target) {
  if (!sourceCache.has(target)) {
    const sourceFile = path.join(sourceRoot, `${target}.json`);
    sourceCache.set(target, readJSON(sourceFile).content);
  }
  return sourceCache.get(target);
}

