for (const relative of fs.readdirSync(translationRoot).filter((file) => file.endsWith(".json")).sort()) {
  const file = path.join(translationRoot, relative);
  const document = readJSON(file);
  let fileChanged = false;
  for (const change of document.Changes ?? []) {
    const source = sourceContent(change.Target);
    for (const [key, oldValue] of Object.entries(change.Entries ?? {})) {
      const original = source[key];
      let newValue = oldValue;
      const appliedRules = [];
      for (const rule of rules) {
        rule.source.lastIndex = 0;
        if (!rule.source.test(original)) continue;
        if (rule.excludeSource?.test(original)) continue;
        if (rule.includeRecord && !rule.includeRecord({ target: change.Target, key, original })) continue;
        const beforeRule = newValue;
        for (const [expression, replacement] of rule.replacements) {
          newValue = newValue.replace(expression, replacement);
        }
        if (newValue !== beforeRule) appliedRules.push(rule.id);
      }
      const eventReplacements = eventEditorialReplacements.get(`${change.Target}\0${key}`) ?? [];
      const beforeEventReplacements = newValue;
      if (change.Target.startsWith("Data/Events/")) {
        for (const [expression, replacement] of globalEventEditorialReplacements) {
          newValue = newValue.replaceAll(expression, replacement);
        }
      }
      for (const [expression, replacement] of eventReplacements) {
        newValue = newValue.replaceAll(expression, replacement);
      }
      if (newValue !== beforeEventReplacements) appliedRules.push("event-editorial-replacement");
      const override = editorialOverrides.get(`${change.Target}\0${key}`);
      if (override !== undefined && newValue !== override) {
        newValue = override;
        appliedRules.push("editorial-override");
      }
      if (newValue === oldValue) continue;
      change.Entries[key] = newValue;
      fileChanged = true;
      changes.push({ relative, target: change.Target, key, rules: appliedRules, original, oldValue, newValue });
    }
  }
  if (apply && fileChanged) fs.writeFileSync(file, `${JSON.stringify(document, null, 2)}\n`);
}

const summary = new Map();
for (const change of changes) {
  for (const rule of change.rules) summary.set(rule, (summary.get(rule) ?? 0) + 1);
}
console.log(JSON.stringify({
  mode: apply ? "apply" : "dry-run",
  changedRecords: changes.length,
  byRule: Object.fromEntries([...summary].sort()),
}, null, 2));
for (const change of changes.slice(0, 80)) {
  console.log(`${change.relative}\t${change.key}\t${change.rules.join(",")}\t${JSON.stringify(change.oldValue)} -> ${JSON.stringify(change.newValue)}`);
}
if (changes.length > 80) console.log(`... ${changes.length - 80} more changes`);
